// custom error tanpa class: buat Error biasa lalu tambahkan name dan data
function buatValidasiError(field, pesan) {
  const e = new Error(pesan);
  e.name = 'ValidasiError';
  e.field = field;
  return e;
}
function buatTidakDitemukanError(pesan) {
  const e = new Error(pesan);
  e.name = 'TidakDitemukanError';
  e.status = 404;
  return e;
}

function daftar(user) {
  if (!user.email.includes('@')) throw buatValidasiError('email', 'Format email salah');
  if (user.email === 'ada@contoh.id') throw buatTidakDitemukanError('Paket tidak ditemukan');
  return 'terdaftar';
}

for (const u of [{ email: 'rina@contoh.id' }, { email: 'rina' }, { email: 'ada@contoh.id' }, null]) {
  try {
    console.log(daftar(u));
  } catch (e) {
    if (e.name === 'ValidasiError') console.log(`[400] ${e.field}: ${e.message}`);
    else if (e.name === 'TidakDitemukanError') console.log(`[${e.status}] ${e.message}`);
    else console.log(`[500] bug: ${e.name} - ${e.message}`);
  }
}
const e = buatValidasiError('nama', 'wajib');
console.log(e instanceof Error, e.stack.split('\n')[0]);

for (const kode of ['null.x', 'x.y.z', 'new Array(-1)', '[].reduce((a,b)=>a)']) {
