function pesan(stok, jumlah) {
  if (jumlah > stok) {
    const e = new Error(`stok hanya ${stok}`);
    e.name = 'StokError';
    e.kekurangan = jumlah - stok;
    throw e;
  }
  return 'pesanan diterima';
}
try {
