class Buku {
  constructor(judul, penulis, stok) {
    this.judul = judul;
    this.penulis = penulis;
    this.stok = stok;
  }
  pinjam() {
    if (this.stok === 0) return `${this.judul} sedang habis`;
    this.stok--;
    return `${this.judul} dipinjam, sisa ${this.stok}`;
  }
}
