let dihitung = 0;
const cache = new Map();
function ongkirKeKota(kota) {
  if (cache.has(kota)) return cache.get(kota);
  dihitung++;
  const hasil = kota.length * 1000;     // anggap perhitungan mahal
  cache.set(kota, hasil);
  return hasil;
}
['Bandung', 'Medan', 'Bandung', 'Bandung'].forEach(k => ongkirKeKota(k));
